import numpy as np
from scipy import stats

MAX_DRIVERS = 4

def design(feats):
    # Check if we have enough patients and features
    if feats.n < 10 or len(feats.ids) < 2:
        return Design(drivers=(), columns=(), products=(), loadings={})

    # Compute t-statistics for all features
    t_stats = []
    for i, fid in enumerate(feats.ids):
        y1 = feats.x[feats.y == 1, i]
        y0 = feats.x[feats.y == 0, i]
        if len(y1) > 0 and len(y0) > 0:
            t_stat, _ = stats.ttest_ind(y1, y0, equal_var=False)
            t_stats.append(abs(t_stat))
        else:
            t_stats.append(0.0)

    # Select top features by t-statistic
    top_indices = np.argsort(t_stats)[::-1][:MAX_DRIVERS]
    drivers = [feats.ids[i] for i in top_indices if t_stats[i] > 2.0]

    # Build columns and products
    columns = list(feats.ids)

    # Add pairwise interactions between highly correlated features
    products = []
    for i in range(len(columns)):
        for j in range(i+1, len(columns)):
            # Check correlation threshold
            corr = np.corrcoef(feats.x[:, i], feats.x[:, j])[0, 1]
            if abs(corr) >= 0.6:
                products.append((columns[i], columns[j]))

    # Create weighted loading score from top features
    loadings = {}
    for i, fid in enumerate(feats.ids):
        if i < 10:  # Top 10 features
            # Weight by t-statistic
            loadings[fid] = t_stats[i]

    # Normalize loadings
    total = sum(loadings.values())
    if total > 0:
        for k in loadings:
            loadings[k] /= total

    # Limit to reasonable number of terms
    if len(loadings) > 12:
        # Keep top 12 by weight
        sorted_items = sorted(loadings.items(), key=lambda x: x[1], reverse=True)
        loadings = dict(sorted_items[:12])

    return Design(
        drivers=tuple(drivers),
        columns=tuple(columns),
        products=tuple(products),
        loadings=loadings
    )
